@click.group()
def registry() -> None:
    """Inspect the local ONEX registry and configured backends."""


def _count_entry_points(group: str) -> int:
    """Return the number of entry points registered under ``group``."""
    from importlib.metadata import entry_points

    try:
        eps = entry_points()
        select = getattr(eps, "select", None)
        if select is not None:
            return len(select(group=group))
        return len(eps.get(group, ()))  # type: ignore[union-attr]
    except Exception:
        return 0


@registry.command("status")
def registry_status() -> None:
    """Show registry status, backend wiring, and discovered nodes."""
    click.echo("Registry status")
    click.echo(
        "EventBus: backend=default (source: default, package: omnibase_core)"
    )
    click.echo("StateStore: default (package: omnibase_core)")
    click.echo(f"Nodes: {_count_entry_points('onex.nodes')} discovered")
    click.echo(
        f"Backends: {_count_entry_points('onex.backends')} registered "
        "(entry-point group: onex.backends)"
    )
    click.echo(
        f"CLI: {_count_entry_points('onex.cli')} extensions "
        "(entry-point group: onex.cli)"
    )


